def write(path,obj):
 path.parent.mkdir(parents=True,exist_ok=True);path.write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
for doc,rows in NEW.items():
 bundle=json.loads((ROOT/f'data/retrieval/reference-cards/{doc}.json').read_text())
 for i,(page,section,purpose,paraphrase) in enumerate(rows,6):
  bundle['fragments'].append(dict(fragment_id=f'{doc}-F{i:02}',page=page,section=section,claim_type='fact',paraphrase=paraphrase,quote=None,required_context=[],purpose=purpose,volume_justification='Один выбранный справочный факт для вопроса HAC, изложенный самостоятельно; границы HAC явно отделены. Не воспроизводятся таблицы, алгоритмы, полная последовательность глав или текст шкал.'))
 write(ROOT/f'data/retrieval/packages/J02B/{doc}.json',bundle)
print('Built',sum(len(v) for v in NEW.values()),'new authored facts; prior fragments preserved')
